namespace Claims;

public sealed class ClaimAdjudicator
{
    public ClaimDecision Evaluate(Claim? claim, ICoverageRegister coverageRegister, IRiskScreen riskScreen)
    {
        if (claim is null)
            return new ClaimDecision("rejected", 0m, ["missing-claim"]);

        var reasons = CollectClaimReasons(claim);
        var coverage = coverageRegister.Find(claim.PolicyNumber);

        AddCoverageReasons(coverage is not null, coverage?.Active ?? false, coverage?.CoversCategory ?? false, reasons);
        AddRiskReasons(riskScreen.Score(claim), reasons);

        if (HasRejectionReason(reasons))
            return new ClaimDecision("rejected", 0m, reasons);

        if (RequiresReview(reasons))
            return new ClaimDecision("review", 0m, reasons);

        return CalculateApprovedDecision(
            claim.ClaimedAmount,
            claim.PriorPaidAmount,
            coverage!.Deductible,
            coverage.Limit,
            reasons);
    }

    private static List<string> CollectClaimReasons(Claim claim)
    {
        var reasons = new List<string>();

        if (string.IsNullOrWhiteSpace(claim.Reference))
            reasons.Add("missing-reference");
        if (string.IsNullOrWhiteSpace(claim.PolicyNumber))
            reasons.Add("missing-policy");
        if (claim.ClaimedAmount <= 0m)
            reasons.Add("invalid-amount");
        if (claim.DaysAfterIncident < 0)
            reasons.Add("invalid-incident-age");
        if (claim.DaysAfterIncident > 90)
            reasons.Add("late-notification");
        if (!claim.DocumentsComplete)
            reasons.Add("documents-incomplete");
        if (claim.Category == "theft" && !claim.PoliceReportPresent)
            reasons.Add("police-report-required");

        return reasons;
    }

    private static void AddCoverageReasons(
        bool coverageExists,
        bool coverageIsActive,
        bool categoryIsCovered,
        List<string> reasons)
    {
        if (!coverageExists)
            reasons.Add("unknown-policy");
        else if (!coverageIsActive)
            reasons.Add("inactive-policy");
        else if (!categoryIsCovered)
            reasons.Add("excluded-category");
    }

    private static void AddRiskReasons(int riskScore, List<string> reasons)
    {
        if (riskScore >= 80)
            reasons.Add("manual-risk-review");
        else if (riskScore < 0)
            reasons.Add("invalid-risk-score");
    }

    private static bool HasRejectionReason(IEnumerable<string> reasons) =>
        reasons.Any(reason => reason is
            "missing-reference" or
            "missing-policy" or
            "invalid-amount" or
            "invalid-incident-age" or
            "unknown-policy" or
            "inactive-policy" or
            "excluded-category" or
            "police-report-required");

    private static bool RequiresReview(IEnumerable<string> reasons) =>
        reasons.Any(reason => reason is
            "documents-incomplete" or
            "late-notification" or
            "manual-risk-review");

    private static ClaimDecision CalculateApprovedDecision(
        decimal claimedAmount,
        decimal priorPaidAmount,
        decimal deductible,
        decimal coverageLimit,
        List<string> reasons)
    {
        var payable = Math.Max(0m, claimedAmount - deductible);
        payable = Math.Min(payable, Math.Max(0m, coverageLimit - priorPaidAmount));

        return payable == 0m
            ? new ClaimDecision("declined-no-benefit", 0m, [.. reasons, "no-benefit-remaining"])
            : new ClaimDecision("approved", decimal.Round(payable, 2), reasons);
    }
}
